'use strict';
const $=id=>document.getElementById(id);let curriculum=[],grade=1,current=null,modelId='',state={},discoveries={};
try{discoveries=JSON.parse(localStorage.getItem('math-discovery-v1')||'{}');if(!discoveries||Array.isArray(discoveries)||typeof discoveries!=='object')discoveries={}}catch(e){discoveries={}}
const terms=['','First Term','Second Term','Third Term'];
function defaults(id){return Object.fromEntries(M[id].controls.filter(c=>c.type!=='button').map(c=>[c.key,c.value]))}
function updateCount(){$('count').textContent=Object.keys(discoveries).length}
function thumb(r){const art=COMPETENCY_ART[r.id];if(!art)return '';const col=art.cell%6,row=Math.floor(art.cell/6);return `<span class="competency-thumb" aria-hidden="true" style="background-image:url('assets/competencies-grade-${art.grade}.webp');background-position:${col*20}% ${row*25}%"></span>`}

let selectedWeekly=null;
function termRows(){let term=+$('term').value;return curriculum.filter(r=>r.grade===grade&&(!term||r.term===term))}
function filtered(){return termRows().filter(r=>!selectedWeekly||r.id===selectedWeekly.id)}
function selectWeekly(id,index){
 selectedWeekly=id?{id,index}:null;renderCards();$('competencyPicker').open=false;$('competencyPicker').querySelector('summary').focus();
}
function renderWeekly(){
 const rows=termRows(),chosen=selectedWeekly&&rows.find(r=>r.id===selectedWeekly.id);
 $('selectedCompetency').textContent=chosen?`${terms[chosen.term]} · Week ${chosen.weeks} — ${chosen.competencies[selectedWeekly.index]}`:'All weekly competencies';
 $('weeklyList').innerHTML='<button type="button" class="competency-option" data-weekly-id="" data-focus="0">All weekly competencies</button>'+rows.map(r=>`<section class="weekly-group"><h4>${terms[r.term]} · Week ${esc(r.weeks)}</h4>${r.competencies.map((c,i)=>`<button type="button" class="competency-option" data-weekly-id="${r.id}" data-focus="${i}" aria-pressed="${!!(chosen&&chosen.id===r.id&&selectedWeekly.index===i)}">${esc(c)}</button>`).join('')}</section>`).join('');
 $('weeklyList').querySelectorAll('[data-weekly-id]').forEach(b=>b.onclick=()=>selectWeekly(b.dataset.weeklyId,+b.dataset.focus));
}
$('competencyPicker').addEventListener('keydown',e=>{if(e.key==='Escape'){$('competencyPicker').open=false;$('competencyPicker').querySelector('summary').focus()}});
document.addEventListener('click',e=>{if(!$('competencyPicker').contains(e.target))$('competencyPicker').open=false});
function renderCards(){document.querySelectorAll('.grades button').forEach(b=>{let active=+b.dataset.grade===grade;b.classList.toggle('active',active);b.setAttribute('aria-pressed',active)});let rows=filtered();renderWeekly(rows);$('resultsTitle').textContent=`Grade ${grade} discoveries`;$('resultsCount').textContent=rows.length+' competency groups';$('cards').innerHTML=rows.length?rows.map(r=>`<button class="card" data-id="${r.id}"><div class="thumb"><span class="tag">${r.models.length} ${r.models.length===1?'model':'models'}</span>${thumb(r)}</div><div class="card-body"><div class="meta">${terms[r.term]} · Week ${r.weeks}</div><h3>${esc(r.competencies[0]||M[r.models[0]].title)}</h3><p>${esc(r.competencies.length>1?'Also: '+r.competencies.slice(1).join(' '):'Explore with '+r.models.map(id=>M[id].title).join(' · '))}</p><div class="card-bottom"><span>${r.models.some(m=>discoveries[r.id+':'+m])?'✓ Discovery saved':'Explore · Predict · Explain'}</span><strong>Open lab</strong></div></div></button>`).join(''):'<div class="empty">No matching competencies. Choose another term or weekly competency.</div>';document.querySelectorAll('.card').forEach(b=>b.addEventListener('click',()=>{openLab(b.dataset.id);if(selectedWeekly&&selectedWeekly.id===b.dataset.id){focusIndex=selectedWeekly.index;renderFocus()}}));}
function chooseGrade(g){grade=g;selectedWeekly=null;renderCards();history.replaceState(null,'','#grade='+g)}
let focusIndex=0,ownsFullscreen=false;
function openLab(id,selected){current=curriculum.find(r=>r.id===id);if(!current)return;$('labMeta').textContent=`Grade ${current.grade} / ${terms[current.term]} / Week ${current.weeks}`;$('competencyText').innerHTML='<ul>'+current.competencies.map(x=>'<li>'+esc(x)+'</li>').join('')+'</ul><p class="note">Source: '+esc(current.source)+'. Competency wording is extracted from the supplied PDF; mathematical superscripts and line breaks may be simplified by PDF extraction.</p><p class="note">Choose a companion model below. Each model explores a specific idea; the complete weekly competencies may also require contextual problems, constructions, or written proofs.</p>';$('labTabs').innerHTML=current.models.map(id=>`<button data-model="${id}">${esc(M[id].title)}</button>`).join('');$('labTabs').querySelectorAll('button').forEach(b=>b.onclick=()=>selectModel(b.dataset.model));focusIndex=0;$('focusSelect').innerHTML=current.competencies.map((c,i)=>`<option value="${i}">Competency ${i+1} of ${current.competencies.length}</option>`).join('');renderFocus();if(!$('lab').open)$('lab').showModal();selectModel(selected&&current.models.includes(selected)?selected:current.models[0]);}
function selectModel(id){modelId=id;let prior=discoveries[current.id+':'+id];state=defaults(id);if(prior&&prior.state)for(let c of M[id].controls){let v=prior.state[c.key];if(v!==undefined&&c.type!=='button')state[c.key]=c.type==='range'||c.type==='number'?Math.max(c.min,Math.min(c.max,Number(v)||0)):v}if(!prior){if(id==='place'){state.n=current.grade===1?42:current.grade===2?356:current.grade===3?2547:438215;if(/decimal/i.test(current.text)){state.digits=current.grade===4?2:current.grade===5?3:4;state.n=3456}}if(id==='fraction'&&current.grade===1){state.a=1;state.b=2;state.c=1;state.d=4}if(id==='data'){if(/double bar/i.test(current.text))state.view='Double bar graph';else if(/double line/i.test(current.text))state.view='Double line graph';else if(/pie graph/i.test(current.text))state.view='Pie graph';else if(/pictograph/i.test(current.text))state.view='Pictograph';else if(/box-and-whisker/i.test(current.text))state.view='Box plot';else if(/line graph/i.test(current.text))state.view='Line graph'}if(id==='fraction'){if(/multiply|multiplication/i.test(current.text))state.op='Multiply';else if(/divide|division/i.test(current.text))state.op='Divide';else if(/add/i.test(current.text))state.op='Add'}if(id==='numberline'){if(/divide|division/i.test(current.text))state.op='÷';else if(/multiply|multiplication/i.test(current.text))state.op='×';else if(/subtract/i.test(current.text))state.op='−'}if(id==='linear'&&/system/i.test(current.text))state.view='Two lines';if(id==='angle'&&/parallel/i.test(current.text))state.view='Parallel lines & transversal';if(id==='solid'){if(/cylinder/i.test(current.text))state.shape='Cylinder';else if(/cone/i.test(current.text))state.shape='Cone';else if(/pyramid/i.test(current.text))state.shape='Square pyramid'}}$('readout').hidden=false;$('reveal').textContent='Hide result';$('reveal').setAttribute('aria-expanded','true');$('labTitle').textContent=M[id].title;$('prompt').textContent=M[id].prompt;$('reflection').value=prior?.note||'';$('saveStatus').textContent='';$('teacherPrompt').textContent='Discussion focus: '+M[id].prompt;$('labTabs').querySelectorAll('button').forEach(b=>{b.classList.toggle('active',b.dataset.model===id);b.setAttribute('aria-pressed',b.dataset.model===id)});renderControls();draw();}
function renderControls(){$('controls').innerHTML=M[modelId].controls.map(c=>`<div class="control">${c.type==='button'?`<button class="action" data-action="${c.key}">${esc(c.label)}</button>`:`<label for="ctl-${c.key}">${esc(c.label)}${c.type==='range'?`<output id="val-${c.key}">${esc(state[c.key])}</output>`:''}</label>${c.type==='select'?`<select id="ctl-${c.key}" data-key="${c.key}">${c.options.map(v=>`<option ${state[c.key]===v?'selected':''}>${esc(v)}</option>`).join('')}</select>`:`<input id="ctl-${c.key}" data-key="${c.key}" type="${c.type}" value="${esc(state[c.key])}" ${c.min!==undefined?`min="${c.min}" max="${c.max}" step="${c.step}"`:''}>`}`}</div>`).join('');$('controls').querySelectorAll('[data-key]').forEach(el=>el.addEventListener('input',()=>{let c=M[modelId].controls.find(c=>c.key===el.dataset.key),v=el.value;if(c.type==='range'||c.type==='number'){v=Number(v);if(!Number.isFinite(v))return;v=Math.min(c.max,Math.max(c.min,v))}state[c.key]=v;if(modelId==='probability'){state.trials=0;state.greenHits=0}if($('val-'+c.key))$('val-'+c.key).textContent=v;draw();$('saveStatus').textContent=''}));$('controls').querySelectorAll('[data-action]').forEach(el=>el.onclick=()=>{if(modelId==='probability'){let n=el.dataset.action==='hundred'?100:1;for(let i=0;i<n;i++){let t=state.trials||0,h=state.greenHits||0,r=state.red-(state.replace==='Without replacement'?h:0),g=state.gold-(state.replace==='Without replacement'?t-h:0);if(r+g<=0)break;state.greenHits=h+(Math.random()<r/(r+g)?1:0);state.trials=t+1}draw()}})}
function draw(){try{let [pic,result]=M[modelId].render(state);$('canvas').innerHTML=pic;$('readout').innerHTML=result}catch(e){$('canvas').textContent='Please check the values entered.';$('readout').textContent='Use values within the control limits.'}}
$('reset').onclick=()=>{state=defaults(modelId);renderControls();draw();$('saveStatus').textContent='Model reset.'};$('save').onclick=()=>{let note=$('reflection').value.trim();if(!note){$('saveStatus').textContent='Write an observation or prediction first.';$('reflection').focus();return}let entry={id:current.id,model:modelId,title:M[modelId].title,grade:current.grade,term:current.term,weeks:current.weeks,note,state:{...state},date:new Date().toISOString()};try{let next={...discoveries,[current.id+':'+modelId]:entry};localStorage.setItem('math-discovery-v1',JSON.stringify(next));discoveries=next;updateCount();renderCards();$('saveStatus').textContent='Saved on this device. You can find it in My discoveries.'}catch(e){$('saveStatus').textContent='This browser cannot save locally. Copy your observation before closing.'}};
function renderFocus(){
 $('focusSelect').value=focusIndex;$('focusText').textContent=current.competencies[focusIndex];
 $('focusTask').textContent=current.review?.discussion[focusIndex]||'Predict, test two examples, explain, and complete the competency with written work.';
 $('prevFocus').disabled=focusIndex===0;$('nextFocus').disabled=focusIndex===current.competencies.length-1;
}
function presentation(on){
 $('lab').classList.toggle('presenting',on);$('present').textContent=on?'Exit presentation':'Present to class';$('present').setAttribute('aria-pressed',String(on));
 $('presentationStatus').textContent=on?'Presentation view. Controls remain interactive. Hide the result to ask for predictions; press Escape to exit.':'';
 $('lab').scrollTop=0;
}
$('focusSelect').onchange=e=>{focusIndex=+e.target.value;renderFocus()};
$('prevFocus').onclick=()=>{if(focusIndex>0){focusIndex--;renderFocus()}};
$('nextFocus').onclick=()=>{if(focusIndex<current.competencies.length-1){focusIndex++;renderFocus()}};
$('toggleFocus').onclick=()=>{let hidden=!$('focusBody').hidden;$('focusBody').hidden=hidden;$('toggleFocus').textContent=hidden?'Show discussion':'Hide discussion';$('toggleFocus').setAttribute('aria-expanded',String(!hidden))};
$('reveal').onclick=()=>{let hidden=!$('readout').hidden;$('readout').hidden=hidden;$('reveal').textContent=hidden?'Reveal result':'Hide result';$('reveal').setAttribute('aria-expanded',String(!hidden))};
$('present').onclick=()=>{const on=!$('lab').classList.contains('presenting');presentation(on);if(!on&&ownsFullscreen&&document.fullscreenElement)document.exitFullscreen?.().catch(()=>{})};
$('closeLab').onclick=()=>{$('lab').close()};
$('lab').addEventListener('close',()=>{presentation(false);if(ownsFullscreen&&document.fullscreenElement)document.exitFullscreen?.().catch(()=>{})});
$('lab').addEventListener('cancel',e=>{if($('lab').classList.contains('presenting')){e.preventDefault();presentation(false)}});
$('fullscreen').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else{presentation(true);await document.documentElement.requestFullscreen();ownsFullscreen=true}}catch(e){$('presentationStatus').textContent='Fullscreen is unavailable. The enlarged presentation view is still ready to use.'}};
document.addEventListener('fullscreenchange',()=>{if(!document.fullscreenElement)ownsFullscreen=false;$('fullscreen').textContent=document.fullscreenElement?'Exit fullscreen':'Fullscreen'});
$('info').querySelector('.close-info').onclick=()=>$('info').close();
$('teacher').onclick=()=>{$('infoBody').innerHTML='<p class="eyebrow">TEACH WITH CURIOSITY</p><h2>Give ideas room to grow.</h2><p>Choose the grade, term, and week from your Budget of Work. Open a lab and expand the competencies to see the source wording.</p><ol><li><b>Explore:</b> Give learners two minutes to investigate the model.</li><li><b>Predict:</b> Ask what will happen before moving a control.</li><li><b>Explain:</b> Compare examples and justify the pattern.</li><li><b>Extend:</b> Use a local context, written solution, or proof to address the full competency.</li></ol><p>Use Present to class for an enlarged classroom view, or Fullscreen to fill the display. Select a discussion competency and use Hide result / Reveal result for predictions. All controls work with keyboard input and touch. Notes are stored only in the current browser, without names or accounts. Shared devices share the same notes.</p><p><b>Coverage:</b> 506 competency entries in 254 source groups cover all 300 grade–term–week slots. The review corrected model assignments in 76 groups and added 11 companion models. Each competency includes a teacher completion task. Some areas still need worked examples, physical constructions, or proofs; this is not a claim of complete simulation coverage or mastery.</p><p><a href="coverage-review.html" target="_blank" rel="noopener">Read the competency coverage review and remaining teaching tasks</a>.</p>';$('info').showModal()};
$('progress').onclick=()=>{let entries=Object.entries(discoveries);$('infoBody').innerHTML='<p class="eyebrow">YOUR EXPLORATION NOTEBOOK</p><h2>My discoveries</h2><p>Saved in this browser only. Export your notes to keep a copy.</p>'+ (entries.length?'<button id="exportNotes">Export notes</button>'+entries.map(([key,e])=>`<article class="discovery"><b>${esc(e.title)} · Grade ${e.grade}</b><p>${terms[e.term]} · Week ${esc(e.weeks)}</p><p>${esc(e.note)}</p><button data-reopen="${esc(key)}">Reopen model</button></article>`).join(''):'<p>No discoveries saved yet. Explore a model, write what you notice, and select Save discovery.</p>');$('infoBody').querySelectorAll('[data-reopen]').forEach(b=>b.onclick=()=>{let e=discoveries[b.dataset.reopen];$('info').close();openLab(e.id,e.model)});if($('exportNotes'))$('exportNotes').onclick=()=>{let text=entries.map(([,e])=>`${e.title}\nGrade ${e.grade} | ${terms[e.term]} | Week ${e.weeks}\n${e.note}\n`).join('\n'),url=URL.createObjectURL(new Blob([text],{type:'text/plain'})),a=document.createElement('a');a.href=url;a.download='Math_Discovery_Notes.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};$('info').showModal()};
$('grades').innerHTML=Array.from({length:10},(_,i)=>`<button data-grade="${i+1}"><span>GRADE</span><b>${i+1}</b></button>`).join('');$('grades').querySelectorAll('button').forEach(b=>b.onclick=()=>chooseGrade(+b.dataset.grade));$('term').addEventListener('change',()=>{selectedWeekly=null;renderCards()});updateCount();fetch('curriculum.json?v=classroom-4').then(r=>{if(!r.ok)throw Error('load');return r.json()}).then(data=>{curriculum=data;let g=Number(location.hash.match(/grade=(\d+)/)?.[1]);if(g>=1&&g<=10)grade=g;renderCards()}).catch(()=>$('cards').innerHTML='<div class="empty">The competency list could not load. Please refresh the page when your connection is available.</div>');
